import csv

# Check RFC 4180 compliance - each row should have same number of fields
def check_csv(filename):
    with open(filename, 'r', newline='', encoding='utf-8') as f:
        reader = csv.reader(f)
        header = next(reader)
        header_len = len(header)
        errors = []
        for i, row in enumerate(reader, start=2):
            if len(row) != header_len:
                errors.append(f'Row {i}: {len(row)} fields instead of {header_len}')
        return errors

errors_stops = check_csv('outputs/t05_clean_stops.csv')
errors_stop_times = check_csv('outputs/t05_clean_stop_times.csv')

if errors_stops:
    print('Errors in t05_clean_stops.csv:')
    for e in errors_stops[:10]:
        print(e)
else:
    print('t05_clean_stops.csv: OK')

if errors_stop_times:
    print('Errors in t05_clean_stop_times.csv:')
    for e in errors_stop_times[:10]:
        print(e)
else:
    print('t05_clean_stop_times.csv: OK')
""}

